<script setup lang="ts">
import {ref,watch} from 'vue';
import type {World,Point} from '../../../packages/shared/src/types';
const props=defineProps<{world:World;tile?:Point;tab:string}>(),emit=defineEmits(['updated']);
const text=ref('在东面建一座水塔，预算4000金币'),draft=ref<any>(),error=ref(''),message=ref(''),resource=ref('food'),amount=ref(10),price=ref(3),from=ref<Point>(),zone=ref('HOUSING');
async function api(path:string,b?:any){const r=await fetch(path,{method:b?'POST':'GET',headers:{'content-type':'application/json'},body:b?JSON.stringify(b):undefined});const j=await r.json();if(!r.ok)throw new Error(j.message);return j;}
const base=()=>`/api/worlds/${props.world.id}`;
async function command(path:string,b:any){try{emit('updated',await api(base()+path,{...b,key:crypto.randomUUID(),expectedVersion:props.world.version}));error.value='';}catch(e:any){error.value=e.message;}}
async function parse(){try{draft.value=await api('/api/proposals/parse',{text:text.value});message.value='这是草案，尚未审议或执行。';error.value='';}catch(e:any){error.value=e.message;}}
async function validate(){try{if(!draft.value.site)throw new Error('请点击地图选址');await api(base()+'/blueprints/validate',{type:draft.value.structureType,site:draft.value.site,rotation:draft.value.rotation??0});message.value='地块初查通过；预算、招工与正式施工仍需审议。';error.value='';}catch(e:any){error.value=e.message;}}
watch(()=>props.tile,p=>{if(p&&draft.value)draft.value.site={...p};});
</script>
<template><div v-if="tab==='finance'"><h2>财政与资源</h2><p>公共余额 {{Math.round(world.resources.cash)}} · 预留 {{Math.round(Object.values(world.reservations??{}).reduce((n:number,r:any)=>n+r.cash,0))}}</p><p v-if="world.resources.water<30" class="error">缺水预警：请审议节水或贸易补给。</p><h3>商队采购</h3><select v-model="resource"><option v-for="r in ['food','water','wood','stone','tools']">{{r}}</option></select><label>数量<input type="number" min="1" v-model.number="amount"></label><label>单价（须符合报价）<input type="number" min="0" v-model.number="price"></label><button @click="command('/trade',{resource,amount,price})">确认采购</button><h3>最新流水</h3><p v-for="j in (world.ledger??[]).slice(-15).reverse()">{{j.reason}} · {{j.entries[0].debit.toFixed(2)}} 金币</p><p v-for="t in (world.inventoryTransactions??[]).slice(-10).reverse()">{{t.resource}} {{t.delta.toFixed(2)}} · {{t.reason}}</p></div>
<div v-else-if="tab==='projects'"><h2>建设项目</h2><div v-for="j in world.projects" class="notice"><strong>{{j.type}} · {{j.status}}</strong><p>{{Math.round(j.progress*100)}}% · 已耗{{Math.round(j.cashSpent)}}金币</p><progress :value="j.progress" max="1"></progress><p>{{j.reason}}</p><p>工人 {{j.workers.map((id:string)=>world.residents.find(r=>r.id===id)?.name).join('、')||'等待志愿者'}}</p><button v-if="['STAFFING','IN_PROGRESS'].includes(j.status)" @click="command(`/projects/${encodeURIComponent(j.id)}/control`,{action:'pause'})">暂停</button><button v-if="j.status==='PAUSED'" @click="command(`/projects/${encodeURIComponent(j.id)}/control`,{action:'resume'})">重新招工</button><button v-if="!['COMPLETED','CANCELLED'].includes(j.status)" @click="command(`/projects/${encodeURIComponent(j.id)}/control`,{action:'cancel'})">取消（仅退未耗预留）</button></div></div>
<div v-else><h2>{{tab==='planning'?'地图规划':'镇长提案'}}</h2><p>选中地图地块 {{tile?.x??'—'}}, {{tile?.y??'—'}}。蓝图不等于建成设施。</p><template v-if="tab==='planning'"><h3>框选分区</h3><select v-model="zone"><option v-for="z in ['HOUSING','AGRICULTURE','COMMERCIAL','PUBLIC','PROTECTED']">{{z}}</option></select><button :disabled="!tile" @click="from=tile">设起点</button><button :disabled="!from||!tile" @click="command('/zoning',{from,to:tile,zone})">设终点并提交</button></template><textarea v-model="text" rows="3" aria-label="自然语言提案"></textarea><button @click="parse">生成可编辑草案</button><form v-if="draft" @submit.prevent="command('/proposals',{draft})"><label>标题<input v-model="draft.title"></label><label>类型<select v-model="draft.kind"><option v-for="k in ['CONSTRUCTION','RATIONING','TAX','MIGRATION','OPEN_DISCUSSION']">{{k}}</option></select></label><template v-if="draft.kind==='CONSTRUCTION'"><label>建筑<select v-model="draft.structureType"><option v-for="b in ['WATER_TOWER','HOUSING','FARM','ROAD']">{{b}}</option></select></label><label>预算上限<input v-model.number="draft.budgetCap" type="number" min="0"></label><label>旋转<select v-model.number="draft.rotation"><option v-for="r in [0,90,180,270]" :value="r">{{r}}°</option></select></label><button type="button" @click="validate">校验地块</button><p>选址 {{draft.site?.x??'点击地图'}}, {{draft.site?.y??'待定'}}</p></template><button>提交草案（不直接执行）</button></form><p>{{message}}</p><h3>提案记录</h3><div v-for="p in world.proposals.slice().reverse()" class="notice"><strong>{{p.title}}</strong><p>{{p.status}} · 修订{{p.revision}}</p><p v-for="c in p.comments">{{world.residents.find(r=>r.id===c.residentId)?.name}} {{c.stance}}：{{c.reason}}</p><button v-if="p.status==='DRAFT'" @click="command(`/proposals/${encodeURIComponent(p.id)}/action`,{action:'deliberate'})">启动审查与公议</button><button v-if="['STAFFING','FUNDING_PENDING','APPROVED'].includes(p.status)&&p.kind==='CONSTRUCTION'" @click="command(`/proposals/${encodeURIComponent(p.id)}/action`,{action:'start'})">预留资源并招工</button><button v-if="['REVISION_REQUESTED','REJECTED'].includes(p.status)" @click="command(`/proposals/${encodeURIComponent(p.id)}/action`,{action:'revise',changes:{site:tile,budgetCap:draft?.budgetCap??p.budgetCap}})">按当前选址/预算修订</button><button v-if="['DRAFT','REVISION_REQUESTED','STAFFING','FUNDING_PENDING'].includes(p.status)" @click="command(`/proposals/${encodeURIComponent(p.id)}/action`,{action:'withdraw'})">撤回</button></div></div><p class="error">{{error}}</p></template>
